import {circuitSvg} from './circuit-library.mjs';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export const componentEntries=[
{id:'resistor',title:'Resistencias',family:'Pasivos',mark:'R',intro:'Relacionan tensión y corriente y disipan energía. Su función cambia según dónde estén conectadas.',logic:'En un elemento óhmico, I = V/R. A tensión fija, aumentar R reduce la corriente. P = V²/R permite calcular la disipación.',types:'Fijas, variables y potenciómetros; de película, bobinadas y shunts. Una resistencia de precisión y una de potencia cumplen requisitos diferentes.',use:'Limitar corriente de LED, dividir tensión, fijar niveles lógicos y medir corriente con un shunt.',read:'Código de colores o marcado SMD, valor, tolerancia y potencia. El número R17 es la referencia de posición, no el valor.',measure:'Resistencia con el circuito sin tensión y descargado. Los caminos paralelos pueden reducir la lectura. Si hace falta aislar una pieza, hazlo con procedimiento adecuado.',fault:'Apertura, deriva de valor o daño térmico. Si está quemada, investiga qué causó la disipación excesiva.',example:'Con 5 V entre extremos de 1 kΩ: I = 5 mA y P = 25 mW. Con 2 kΩ, I baja a 2,5 mA.',pattern:'divider',lesson:'potencia',formula:'I = V / R; P = V² / R',q:'Mantienes 5 V y duplicas R. ¿Qué pasa con I?',answers:['Se reduce a la mitad','Se duplica','No cambia'],correct:0,why:'I es inversamente proporcional a R cuando la tensión entre extremos permanece fija.'},
{id:'capacitor',title:'Condensadores / capacitores',family:'Pasivos',mark:'C',intro:'Almacenan carga y energía. Se oponen a cambios instantáneos de tensión y permiten comportamientos distintos en continua y alterna.',logic:'i = C · dv/dt. En un RC, τ = R·C. Durante una carga desde cero, al llegar a τ la tensión es aproximadamente el 63,2 % del valor final.',types:'Cerámicos, electrolíticos, polímero y película. La polaridad, ESR, fuga y tensión admisible importan además de la capacidad.',use:'Filtrado, desacoplo, acoplamiento de audio y temporización.',read:'Capacidad en F, µF, nF o pF; tensión nominal y polaridad cuando corresponda. Un electrolítico no debe invertirse.',measure:'Sin alimentación y con descarga verificada. Capacidad y ESR son medidas diferentes; una capacidad correcta no garantiza una ESR adecuada.',fault:'Pérdida de capacidad, fuga, corto o ESR elevada. Un aspecto normal no descarta un fallo.',example:'Con R = 1 kΩ y C = 1 µF, τ = 1 ms. Desde 0 V hacia 5 V, a 1 ms hay aproximadamente 3,16 V.',pattern:'rc-low',lesson:'pasivos',formula:'τ = R·C; VC(t) = Vfinal(1 − e^(−t/τ))',q:'En un RC desde 0 V, ¿cuánto ha subido VC tras una constante τ?',answers:['100 %','63,2 % aproximadamente','0 %'],correct:1,why:'La carga exponencial alcanza 1−e⁻¹ ≈ 0,632 del salto al llegar a τ.'},
{id:'inductor',title:'Bobinas / inductores',family:'Pasivos',mark:'L',intro:'Almacenan energía magnética y se oponen a cambios instantáneos de corriente.',logic:'v = L · di/dt. Con una tensión constante ideal, la corriente crece con pendiente V/L. La resistencia del bobinado y la saturación limitan el comportamiento real.',types:'Núcleo de aire, ferrita y polvo de hierro; inductores de potencia y choques. Un transformador utiliza bobinados acoplados.',use:'Convertidores conmutados, filtros y almacenamiento de energía. Los relés emplean una bobina para accionar un contacto.',read:'Inductancia, resistencia DC, corriente eficaz y corriente de saturación. La resistencia DC baja puede ser normal.',measure:'Resistencia permite detectar una apertura, pero no garantiza la inductancia ni descarta espiras en corto. Usa el instrumento y las condiciones apropiados.',fault:'Apertura, aislamiento deteriorado, espiras en corto o saturación por corriente excesiva.',example:'Una bobina ideal de 10 mH con 1 V aumenta su corriente a 100 A/s: 100 mA por milisegundo. No extrapoles sin límite en una bobina real.',pattern:'buck',lesson:'pasivos',formula:'di/dt = V/L; E = ½LI²',q:'¿Una bobina con resistencia DC baja está necesariamente en corto?',answers:['Sí','No','Solo si es grande'],correct:1,why:'Un bobinado sano puede tener resistencia DC baja; hacen falta otras pruebas para valorar su comportamiento.'},
{id:'diode',title:'Diodos y LED',family:'Semiconductores',mark:'D',intro:'Su conducción depende de polaridad y tensión. Distingue ánodo A y cátodo K.',logic:'En directa, la corriente aumenta de forma no lineal. Una caída fija de 0,7 V para silicio o 2 V para un LED rojo es una aproximación didáctica, no una especificación universal.',types:'Rectificadores, rápidos, Schottky, LED y fotodiodos. Un Schottky no es un sustituto automático: cambian fuga, tensión y otros límites.',use:'Rectificación, protección de polaridad, rueda libre en cargas inductivas y emisión de luz.',read:'Referencia exacta, marca de cátodo y límites de corriente y tensión inversa. Confirma polaridad con documentación.',measure:'Modo diodo sin tensión y con energía retirada. Compara ambas polaridades, considerando caminos paralelos.',fault:'Abierto, corto o fuga. Una lectura baja en una placa puede deberse a otra rama.',example:'LED rojo ideal de 2 V, fuente de 5 V y R = 1 kΩ: I = 3 mA. La resistencia recibe los 3 V restantes.',pattern:'led',lesson:'diodos',formula:'I ≈ (VIN − VF) / R',q:'En el ejemplo de 5 V y LED de 2 V, ¿qué cae en la resistencia?',answers:['2 V','5 V','3 V'],correct:2,why:'Las caídas del lazo suman la alimentación: 5 V − 2 V = 3 V.'},
{id:'zener',title:'Diodo Zener',family:'Semiconductores',mark:'ZD',intro:'Se utiliza en su región de ruptura inversa para fijar aproximadamente una tensión, dentro de unos límites de corriente y potencia.',logic:'En un limitador sencillo, conecta el cátodo a OUT y el ánodo a GND; una resistencia desde VIN limita la corriente. IZ = (VIN−VZ)/R − Icarga mientras exista regulación.',types:'Distintas tensiones Zener y potencias. Zener y TVS tienen propósitos y especificaciones diferentes; revisa sus fichas.',use:'Referencias sencillas, limitación de tensión y protección de entradas cuando el diseño lo permite.',read:'VZ a su corriente de prueba, tolerancia, potencia, resistencia dinámica y coeficiente de temperatura.',measure:'La función diodo suele comprobar la unión directa, pero normalmente no aporta tensión suficiente para medir VZ. La prueba inversa requiere fuente limitada y cálculo previo.',fault:'Corto, apertura, fuga o tensión fuera de especificación. Investiga la resistencia de limitación y la carga.',example:'VIN = 9 V, VZ ideal = 5,1 V, R = 1 kΩ y sin carga: IZ = 3,9 mA; PZ ≈ 19,9 mW. Es un modelo ideal: confirma corriente mínima de regulación.',pattern:'zener',lesson:'diodos',formula:'IZ = (VIN − VZ)/R − Icarga; PZ = VZ·IZ',q:'¿Qué ocurre si conectas el Zener directamente a una fuente potente sin limitar corriente?',answers:['Regula sin límite','Puede exceder su corriente y dañarse','Se convierte en condensador'],correct:1,why:'La ruptura inversa debe operar con limitación de corriente y respetando la potencia admisible.',source:'https://www.vishay.com/docs/84117/84117.pdf'},
{id:'bjt',title:'Transistores BJT · NPN y PNP',family:'Transistores',mark:'Q',intro:'Tienen base, colector y emisor. Pueden amplificar o trabajar como interruptores; el régimen de funcionamiento es esencial.',logic:'En región activa, IC ≈ β·IB es una aproximación y β varía. En saturación no debes extrapolar esa ganancia; la carga y la alimentación limitan la corriente.',types:'NPN y PNP con polaridades opuestas; señal y potencia. El emisor lleva la flecha en el símbolo: sale en NPN y entra en PNP.',use:'Activar un relé, adaptar niveles o amplificar una señal pequeña.',read:'Pinout exacto, tensión VCE, corriente, potencia, área de operación segura y condiciones térmicas.',measure:'Sin tensión, comprueba uniones como indicio; no demuestra ganancia bajo carga. Con alimentación adecuada, compara VBE y VCE con las condiciones de trabajo.',fault:'Unión en corto o abierta, fuga o degradación. Confirma que la base recibe el mando antes de sustituir.',example:'Con β ideal = 100 e IB = 20 µA, IC sería 2 mA en región activa. Con una carga limitante esa relación ya no determina por sí sola IC.',pattern:'relay',lesson:'transistor',formula:'En activa: IC ≈ β·IB; no usar como ley en saturación',q:'¿Puedes usar β·IB sin límite cuando el transistor está saturado?',answers:['Sí','No','Solo si es NPN'],correct:1,why:'En saturación, la carga y alimentación limitan la corriente y la aproximación de región activa deja de ser válida.'},
{id:'mosfet',title:'Transistores MOSFET',family:'Transistores',mark:'Q',intro:'Tienen puerta G, drenador D y fuente S. Se controlan mediante la tensión puerta-fuente y poseen capacidades que se cargan durante la conmutación.',logic:'Para un NMOS de lado bajo, elevar VGS suficientemente permite conducir. VGS(th) indica inicio de conducción bajo condiciones de prueba, no conducción plena de cualquier carga.',types:'Canal N y canal P; potencia y señal. Debes considerar el diodo interno y la orientación en el circuito.',use:'Conmutar motores y cargas, convertidores y protección de alimentación.',read:'RDS(on) a la VGS especificada, VDS máxima, VGS máxima, carga de puerta y área de operación segura.',measure:'Comprueba mando entre G y S; mide D-S bajo las condiciones apropiadas. Evita dañar la puerta por ESD y no dejes cargas desconocidas en ella.',fault:'D-S en corto, puerta dañada, mando insuficiente o calentamiento excesivo; no todos implican que el componente sea la causa original.',example:'En un modelo con RDS(on) = 0,1 Ω e I = 0,5 A, la caída es 50 mV y la disipación de conducción 25 mW. Faltan pérdidas de conmutación.',pattern:'mosfet',lesson:'transistor',formula:'VDS ≈ I·RDS(on); Pconducción ≈ I²·RDS(on)',q:'¿Qué tensión caracteriza el mando de un MOSFET?',answers:['Puerta respecto a fuente','Puerta respecto a cualquier tierra','Drenador respecto al chasis siempre'],correct:0,why:'Es VGS. La fuente no tiene por qué coincidir con tierra ni con otra referencia del equipo.'}
];
export const filterEntries=[
{id:'rc-low',title:'Paso bajo RC',kind:'lowpass',type:'RC',purpose:'Suavizar una señal lenta, reducir ruido de alta frecuencia y acondicionar entradas.',logic:'R va en serie; C va de OUT a GND. A frecuencias altas, la impedancia del condensador disminuye y atenúa la salida.',formula:'fc = 1/(2πRC)',example:'R = 1 kΩ, C = 100 nF: fc ≈ 1592 Hz. En fc, la amplitud vale 0,707 veces la entrada y la fase es −45°.',fault:'C abierto elimina el filtrado ideal; C en corto lleva OUT a masa. La carga modifica la respuesta.',instrument:'corte'},
{id:'rc-high',title:'Paso alto RC',kind:'highpass',type:'RC',purpose:'Acoplar cambios de señal y atenuar continua o variaciones muy lentas.',logic:'C va en serie; R va de OUT a GND. La salida se toma sobre R. El camino a GND define la referencia de salida.',formula:'fc = 1/(2πRC)',example:'R = 1 kΩ, C = 100 nF: fc ≈ 1592 Hz. En fc, ganancia 0,707 y fase +45°.',fault:'Sin retorno por R, la salida puede quedar flotante. El tiempo de establecimiento importa.',instrument:'offset'},
{id:'rl-low',title:'Paso bajo RL',kind:'rl-low',type:'RL',purpose:'Estudiar cómo una bobina se opone a cambios rápidos de corriente; aparece en filtrado de potencia con topologías específicas.',logic:'L en serie y R desde OUT a GND; salida sobre R. La impedancia de L aumenta con frecuencia.',formula:'fc = R/(2πL)',example:'R = 100 Ω, L = 10 mH: fc ≈ 1592 Hz. La resistencia del bobinado cambia la ganancia y el corte reales.',fault:'Una apertura en L interrumpe el camino; saturación y pérdidas no están incluidas en este modelo.'},
{id:'rl-high',title:'Paso alto RL',kind:'rl-high',type:'RL',purpose:'Comprender una salida sensible a cambios de corriente en un circuito RL. No es un bloqueo de continua aislado por condensador.',logic:'R en serie y L de OUT a GND; salida sobre L. En continua ideal L equivale a un corto y OUT tiende a cero.',formula:'fc = R/(2πL)',example:'R = 100 Ω, L = 10 mH: fc ≈ 1592 Hz. A frecuencias altas la amplitud se aproxima a la entrada ideal.',fault:'La resistencia del bobinado hace que la salida continua real no sea exactamente cero.'},
{id:'rlc-band',title:'Paso banda RLC',kind:'rlc-band',type:'RLC',purpose:'Seleccionar una banda alrededor de una resonancia; estudiar sintonía y selectividad.',logic:'L, C y R forman una rama serie. La salida se toma sobre R. En resonancia se cancelan las reactancias de L y C y la corriente es máxima.',formula:'f0 = 1/(2π√LC); Q = √(L/C)/R; ancho = R/(2πL)',example:'L = 10 mH, C = 100 nF, R = 100 Ω: f0 ≈ 5033 Hz y Q ≈ 3,16. En el modelo ideal la ganancia central es 1.',fault:'Resistencias de fuente, bobina y carga cambian Q y amplitud. No confundas frecuencia central con límites de banda.'},
{id:'rlc-notch',title:'Rechazo de banda · BR / notch',kind:'rlc-notch',type:'RLC',purpose:'Atenuar una banda estrecha no deseada y conservar frecuencias inferiores y superiores.',logic:'R está en serie desde IN a OUT; una rama L-C serie conecta OUT a GND. En resonancia esa rama tiene impedancia ideal cero y deriva la señal.',formula:'f0 = 1/(2π√LC); |H| = |ωL−1/(ωC)| / √(R²+(ωL−1/(ωC))²)',example:'L = 10 mH y C = 100 nF sitúan el rechazo ideal en unos 5033 Hz. La profundidad real está limitada por pérdidas y tolerancias.',fault:'No existe un rechazo infinito real. Un pequeño cambio en L o C desplaza la frecuencia rechazada.',source:'https://www.analog.com/en/resources/technical-articles/a-filter-primer.html'}
];
export const glossary=[['Nodo','Conjunto de terminales conectados directamente por un conductor ideal.'],['GND / referencia','Punto elegido como cero para expresar tensiones; no equivale necesariamente a tierra de protección.'],['Polaridad','Orientación de una tensión o de un componente que distingue sus terminales.'],['Impedancia','Relación compleja tensión/corriente en régimen sinusoidal; incluye resistencia y reactancia.'],['Reactancia','Parte de la impedancia asociada a almacenamiento de energía en bobinas o condensadores.'],['Frecuencia','Número de ciclos por segundo, en Hz; f = 1/T.'],['Ganancia','Relación entre salida y entrada bajo condiciones especificadas.'],['Decibelio','Para relaciones de amplitud de tensión con referencia adecuada: 20 log10(|Vout/Vin|).'],['Frecuencia de corte','En los filtros de primer orden aquí usados, punto de −3,01 dB respecto a la banda pasante.'],['Ancho de banda','Separación entre los límites de frecuencia definidos para una respuesta.'],['Fase','Desplazamiento angular entre señales periódicas de la misma frecuencia.'],['Resonancia','Condición en la que se compensan las reactancias inductiva y capacitiva de una topología.'],['Q / selectividad','Medida asociada a la resonancia y su anchura; depende de la topología y las pérdidas.'],['ESR','Resistencia serie equivalente de un componente, dependiente de las condiciones de medida.'],['Pull-up / pull-down','Resistencia que fija un nivel de reposo alto o bajo en una señal.'],['Desacoplo','Provisión local de corriente transitoria y reducción del acoplamiento no deseado entre circuitos.'],['Saturación','Régimen cuyo significado depende del dispositivo: no equivale en BJT, MOSFET y núcleos magnéticos.'],['BR / band reject','Rechazo de banda. Un notch suele designar un rechazo estrecho alrededor de una frecuencia.']];
export function filterResponse(id,f,R=1000,C=1e-7,L=.01){const w=2*Math.PI*f;if(id.startsWith('rc')){const x=w*R*C,high=id.endsWith('high');return {gain:high?x/Math.hypot(1,x):1/Math.hypot(1,x),phase:(high?Math.PI/2:0)-Math.atan(x),corner:1/(2*Math.PI*R*C)};}if(id.startsWith('rl-')){const x=w*L/R,high=id.endsWith('high');return {gain:high?x/Math.hypot(1,x):1/Math.hypot(1,x),phase:(high?Math.PI/2:0)-Math.atan(x),corner:R/(2*Math.PI*L)};}const x=w*L-1/(w*C),band=id==='rlc-band';return {gain:band?R/Math.hypot(R,x):Math.abs(x)/Math.hypot(R,x),phase:band?-Math.atan2(x,R):(x>=0?Math.PI/2:-Math.PI/2)-Math.atan2(x,R),corner:1/(2*Math.PI*Math.sqrt(L*C))};}
function symbol(kind,x,y,vertical=false){let s='';if(kind==='R')s='<path d="M-45 0H-25 M25 0H45"/><rect x="-25" y="-9" width="50" height="18"/>';if(kind==='C')s='<path d="M-45 0H-7 M-7 -20V20 M7 -20V20 M7 0H45"/>';if(kind==='L')s='<path d="M-45 0H-30 Q-22 -30 -15 0 Q-7 -30 0 0 Q8 -30 15 0 Q23 -30 30 0 H45"/>';if(kind==='D'||kind==='Z')s='<path d="M-45 0H-16 M-16 -17L16 0L-16 17Z M16 0H45 M16 -20V20'+(kind==='Z'?'h-8 M16 -20h8':'')+'"/>';if(kind==='BJT')s='<path d="M-45 0H-12 M-12 -25V25 M-12 -15L25 -40V-50 M-12 15L25 40V50 M25 40L10 34 M25 40L19 25"/>';if(kind==='MOS')s='<path d="M-45 0H-16 M-16 -25V25 M-7 -25V25 M-7 -19H25V-50 M-7 19H25V50 M10 19L0 14 M10 19L0 24"/>';return `<g transform="translate(${x} ${y}) rotate(${vertical?90:0})" fill="none" stroke="#86eac5" stroke-width="3" stroke-linecap="round">${s}</g>`;}
export function atlasSchematic(id){let s='<svg viewBox="0 0 600 330" role="img" aria-label="Circuito de principio con entrada, salida y referencia"><rect width="600" height="330" rx="12" fill="#102936"/><g fill="none" stroke="#a8cddd" stroke-width="3">';const line=d=>s+=`<path d="${d}"/>`,label=(x,y,t)=>s+=`<text x="${x}" y="${y}" stroke="none" fill="#e1f7ff" font-family="sans-serif" font-size="16">${t}</text>`,gnd=()=>line('M430 265v15 m-17 0h34 m-27 8h20 m-14 8h8');
 if(id==='zener'){line('M65 90H155 M245 90H430H540 M430 90V145 M430 235V265');s+=symbol('R',200,90)+symbol('Z',430,190,false).replace('rotate(0)','rotate(-90)');label(62,70,'VIN');label(175,65,'R límite');label(490,70,'OUT');label(463,188,'VZ');label(403,135,'K');label(402,253,'A');gnd();}
 else{let series='R',shunt='C';if(id==='rc-high'){series='C';shunt='R';}if(id==='rl-low'){series='L';shunt='R';}if(id==='rl-high'){series='R';shunt='L';}
 if(id==='rlc-band'){line('M50 90H115 M205 90H255 M345 90H430H540 M430 90V145 M430 235V265');s+=symbol('L',160,90)+symbol('C',300,90)+symbol('R',430,190,true);label(150,50,'L');label(291,50,'C');label(467,197,'R');}
 else if(id==='rlc-notch'){line('M50 90H155 M245 90H430H540 M430 90V105 M430 195V205 M430 295V300');s+=symbol('R',200,90)+symbol('L',430,150,true)+symbol('C',430,250,true);label(190,60,'R');label(468,155,'L');label(468,255,'C');line('M413 303H447 m-27 8h20');}
 else{line('M50 90H155 M245 90H430H540 M430 90V145 M430 235V265');s+=symbol(series,200,90)+symbol(shunt,430,190,true);label(190,55,series);label(467,196,shunt);}
 label(50,70,'IN');label(493,70,'OUT');if(id!=='rlc-notch')gnd();}
 s+='</g></svg>';return s;}
const fmt=n=>Number(n).toLocaleString('es-ES',{maximumFractionDigits:3});
export function mountElectronicsAtlas(api){const $=id=>document.getElementById(id),page=$('libraryPage');let section='components',selected=null,query='';
 const original=document.createElement('div');original.id='atlasCircuitLibrary';while(page.firstChild)original.append(page.firstChild);page.append(original);
 const atlas=document.createElement('section');atlas.id='electronicsAtlas';page.prepend(atlas);
 function render(){atlas.innerHTML=`<div class="atlasHero"><span class="studioKicker">BIBLIOTECA DE CONSULTA · INDEPENDIENTE DEL CURSO</span><h1>Entiende cada pieza.<br><em>Reconoce cada función.</em></h1><p>Consulta un concepto concreto, cambia sus valores y vuelve a tu plan cuando quieras.</p></div><nav class="atlasTabs" aria-label="Secciones de biblioteca">${[['components','Componentes · 7'],['filters','Filtros · 6'],['circuits','Circuitos 3D · 18'],['glossary','Glosario']].map(([id,t])=>`<button data-atlas-tab="${id}" ${section===id?'aria-current="page"':''}>${t}</button>`).join('')}</nav><div id="atlasContent"></div>`;original.hidden=section!=='circuits';atlas.querySelectorAll('[data-atlas-tab]').forEach(b=>b.onclick=()=>{section=b.dataset.atlasTab;selected=null;query='';render();});if(section==='circuits')return;
 $('atlasContent').innerHTML=`<label class="atlasSearch">Buscar en ${section==='components'?'componentes':section==='filters'?'filtros':'el glosario'}<input id="atlasSearch" type="search" value="${esc(query)}" placeholder="${section==='components'?'Zener, bobina, transistor…':section==='filters'?'RC, RL, RLC, BR…':'Nodo, ESR, frecuencia…'}"></label><div id="atlasCards"></div><section id="atlasArticle" hidden></section>`;$('atlasSearch').oninput=e=>{query=e.target.value;cards();};cards();}
 function cards(){const match=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase());const el=$('atlasCards');if(section==='glossary'){el.innerHTML='<dl class="atlasGlossary">'+glossary.filter(x=>match(x.join(' '))).map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')+'</dl>';return;}const list=(section==='components'?componentEntries:filterEntries).filter(x=>match(x.title+' '+(x.family||x.type)+' '+(x.use||x.purpose)));el.innerHTML=`<div class="atlasCardGrid">${list.map(x=>`<button data-atlas-entry="${x.id}"><span>${x.family||x.type}</span><div class="atlasMini">${section==='components'?`<svg viewBox="0 0 130 110" aria-label="Símbolo ${x.title}">${symbol(({resistor:'R',capacitor:'C',inductor:'L',diode:'D',zener:'Z',bjt:'BJT',mosfet:'MOS'})[x.id],65,55)}</svg>`:atlasSchematic(x.id)}</div><h3>${x.title}</h3><p>${x.intro||x.purpose}</p><b>Entender y experimentar →</b></button>`).join('')}</div>${!list.length?'<p>No hay coincidencias. Prueba otro término.</p>':''}`;el.querySelectorAll('[data-atlas-entry]').forEach(b=>b.onclick=()=>open(b.dataset.atlasEntry));}
 function open(id){selected=id;const isFilter=section==='filters',x=(isFilter?filterEntries:componentEntries).find(x=>x.id===id),el=$('atlasArticle');el.hidden=false;let svg=isFilter||id==='zener'?atlasSchematic(id):circuitSvg(({resistor:'divider',capacitor:'lowpass',inductor:'buck',diode:'led',bjt:'relay',mosfet:'mosfet'})[id]);
 el.innerHTML=`<div class="atlasArticleHead"><div><span>${isFilter?'FILTROS / '+x.type:'COMPONENTES / '+x.family}</span><h2>${x.title}</h2></div><button id="closeAtlasArticle" aria-label="Cerrar ficha">×</button></div><p class="atlasLead">${x.intro||x.purpose}</p><div class="atlasColumns"><figure>${svg}<figcaption>${id==='bjt'?'BJT NPN de lado bajo y diodo de rueda libre; símbolo funcional simplificado.':isFilter?'Fuente ideal, sin carga externa. R, L y C ideales.':'Circuito de aplicación didáctico, no pinout de una pieza comercial.'}</figcaption></figure><div><h3>Cómo funciona y por qué</h3><p>${x.logic}</p><div class="atlasFormula">${x.formula}</div><h3>Ejemplo con números</h3><p>${x.example}</p></div></div><section class="atlasExperiment"><span>CAMBIA UN VALOR · OBSERVA LA CONSECUENCIA</span><h3>${isFilter?'Respuesta en frecuencia':'Laboratorio del componente'}</h3><div id="atlasControls"></div><div id="atlasResult" aria-live="polite"></div><div id="atlasPlot"></div><p class="atlasModelNote">${isFilter?'Modelo sinusoidal ideal de pequeña señal, sin carga externa ni resistencias parásitas. La curva muestra amplitud; el punto ámbar indica la frecuencia elegida cuando cae dentro del intervalo mostrado; no predice todos los límites de un filtro real.':'Cálculo ideal del ejemplo indicado. No sustituye la ficha técnica ni una simulación completa.'}</p></section><div class="atlasInfoGrid">${(isFilter?[['Para qué se utiliza',x.purpose],['Qué puede fallar',x.fault],['Cómo medirlo','Generador con seno de amplitud constante; CH1 en IN y CH2 en OUT respecto a la misma referencia. Barre la frecuencia, registra Vout/Vin y fase. Los filtros RL y RLC aquí tienen calculadora; el banco de señales separado usa RC o conexión directa.']]:[['Variantes',x.types],['Usos típicos',x.use],['Qué mirar en la pieza',x.read],['Cómo comprobarlo',x.measure],['Fallos y lógica de diagnóstico',x.fault]]).map(([t,p])=>`<section><h3>${t}</h3><p>${p}</p></section>`).join('')}</div>${!isFilter?`<section class="atlasQuiz"><h3>Comprueba si lo has entendido</h3><p>${x.q}</p>${x.answers.map((a,i)=>`<button data-atlas-answer="${i}">${a}</button>`).join('')}<p id="atlasQuizFeedback" role="status"></p></section>`:'<p><b>Pasivos y activos:</b> los seis ejemplos son pasivos. Los filtros activos añaden operacionales, necesitan alimentación y pueden aportar ganancia. La selección de orden, Q y topología exige comprobar estabilidad, ruido y rango de señal.</p>'}<div class="atlasActions">${!isFilter?'<button id="atlasBackCourse">Estudiar desde su lección del curso →</button>':''}${isFilter&&x.instrument?'<button id="atlasScope">Abrir práctica RC con osciloscopio →</button>':''}<button id="atlasRelated">${isFilter?'Ver circuitos de la biblioteca 3D':'Ver circuitos relacionados'}</button>${x.source?`<a href="${x.source}" target="_blank" rel="noopener noreferrer">Referencia técnica ↗</a>`:''}${isFilter?'<a href="https://www.ti.com/video/6119035031001" target="_blank" rel="noopener noreferrer">Vídeo técnico de TI: circuitos RC (inglés) ↗</a>':''}</div>`;
 $('closeAtlasArticle').onclick=()=>el.hidden=true;el.querySelectorAll('[data-atlas-answer]').forEach(b=>b.onclick=()=>{$('atlasQuizFeedback').textContent=(Number(b.dataset.atlasAnswer)===x.correct?'✓ Correcto. ':'Revisa la idea. ')+x.why;});$('atlasBackCourse')?.addEventListener('click',()=>api.openLesson(x.lesson));$('atlasScope')?.addEventListener('click',()=>document.dispatchEvent(new CustomEvent('circuitlab:instruments',{detail:{lesson:x.instrument}})));$('atlasRelated').onclick=()=>{showCircuits();if(!isFilter&&x.pattern!=='zener')api.openCircuit(x.pattern);};isFilter?filterExperiment(x):componentExperiment(x);document.dispatchEvent(new CustomEvent('circuitlab:lesson-open',{detail:{target:'atlasArticle',id:'atlas:'+id}}));el.scrollIntoView({behavior:'smooth',block:'start'});
 }
 function controls(fields,update){$('atlasControls').innerHTML=fields.map(([id,label,min,max,step,val])=>`<label>${label}<input id="atlas-${id}" type="range" min="${min}" max="${max}" step="${step}" value="${val}"><output id="atlas-${id}-value"></output></label>`).join('');fields.forEach(([id])=>$('atlas-'+id).oninput=update);update();}
 function val(id,unit=''){const n=Number($('atlas-'+id).value);$('atlas-'+id+'-value').textContent=fmt(n)+' '+unit;return n;}
 function componentExperiment(x){const id=x.id;if(id==='resistor')controls([['v','Tensión entre extremos',1,12,.5,5],['r','Resistencia',100,5000,100,1000]],()=>{const v=val('v','V'),r=val('r','Ω');result(`${fmt(v/r*1000)} mA`,`${fmt(v*v/r*1000)} mW disipados · I = ${v}/${r} A`);});
 if(id==='capacitor')controls([['c','Capacidad',.1,10,.1,1],['t','Tiempo tras el escalón',0,10,.1,1]],()=>{const c=val('c','µF'),t=val('t','ms');result(`${fmt(5*(1-Math.exp(-t/c)))} V`,`R = 1 kΩ; escalón 0 → 5 V; τ = ${fmt(c)} ms. Carga desde cero sin carga externa.`);timePlot(t=>5*(1-Math.exp(-t/c)),10,5,'Tiempo (ms)','VC (V)');});
 if(id==='inductor')controls([['l','Inductancia',1,100,1,10],['t','Tiempo con 1 V aplicado',0,2,.1,1]],()=>{const l=val('l','mH'),t=val('t','ms');result(`${fmt(t/l*1000)} mA`,`Inicio desde 0 A; 1 V constante. Pendiente = ${fmt(1000/l)} A/s. Sin resistencia ni saturación: no extrapolar a una bobina real.`);timePlot(t=>t/l*1000,2,2000/l,'Tiempo (ms)','I (mA)');});
 if(id==='diode')controls([['v','Tensión de fuente',0,10,.5,5],['r','Resistencia serie',100,5000,100,1000]],()=>{const v=val('v','V'),r=val('r','Ω');result(`${fmt(Math.max(0,v-2)/r*1000)} mA`,'LED rojo en directa con VF ideal de 2 V. Por debajo de 2 V este modelo de umbral calcula 0 mA.');});
 if(id==='zener')controls([['v','Tensión de entrada',0,12,.5,9],['r','Resistencia limitadora',100,5000,100,1000]],()=>{const v=val('v','V'),r=val('r','Ω'),i=Math.max(0,v-5.1)/r;result(`${fmt(Math.min(v,5.1))} V en OUT`,`Zener ideal 5,1 V sin carga · IZ = ${fmt(i*1000)} mA · PZ = ${fmt(5.1*i*1000)} mW. ${v<=5.1?'No está en ruptura.':'Para una pieza real confirma su corriente mínima y potencia.'}`);});
 if(id==='bjt')controls([['ib','Corriente de base',0,100,5,20],['beta','Ganancia β ideal',50,200,10,100]],()=>{const ib=val('ib','µA'),beta=val('beta');result(`${fmt(ib*beta/1000)} mA calculados`,'Solo aproximación en región activa, sin carga definida. No es una simulación del relé dibujado ni garantiza que esta corriente pueda circular.');});
 if(id==='mosfet')controls([['r','RDS(on) supuesto',.02,1,.02,.1],['i','Corriente de carga',.1,2,.1,.5]],()=>{const r=val('r','Ω'),i=val('i','A');result(`${fmt(i*r)} V de caída`,`${fmt(i*i*r)} W de conducción. Canal encendido al VGS adecuado; no incluye conmutación ni límites térmicos.`);});
 }
 function result(a,b){$('atlasResult').innerHTML=`<strong>${a}</strong><p>${b}</p>`;}
 function timePlot(fn,maxX,maxY,xlabel,ylabel){const pts=Array.from({length:101},(_,i)=>`${55+i*5.1},${215-fn(i/100*maxX)/maxY*160}`).join(' ');$('atlasPlot').innerHTML=`<svg viewBox="0 0 620 270" role="img" aria-label="${ylabel} frente a ${xlabel}"><rect width="620" height="270" rx="12" fill="#0b202b"/><path d="M55 40V215H570" stroke="#7898a8" fill="none"/><polyline points="${pts}" stroke="#77e5b9" fill="none" stroke-width="3"/><g fill="#c5e0ec" font-family="sans-serif" font-size="13"><text x="10" y="25">${ylabel} · máximo ${fmt(maxY)}</text><text x="54" y="238">0</text><text x="505" y="238">${fmt(maxX)}</text><text x="250" y="260">${xlabel}</text></g></svg>`;}
 function filterExperiment(x){const rl=x.type==='RL',rlc=x.type==='RLC';controls([['r','Resistencia R',10,2000,10,rl||rlc?100:1000],...(!rl?[['c','Capacidad C',10,1000,10,100]]:[]),...(rl||rlc?[['l','Inductancia L',1,100,1,10]]:[]),['f','Frecuencia (escala logarítmica)',0,6,.02,3]],()=>{const R=val('r','Ω'),C=rl?1e-7:val('c','nF')*1e-9,L=rl||rlc?val('l','mH')/1000:.01;const f=10**Number($('atlas-f').value);$('atlas-f-value').textContent=fmt(f)+' Hz';const response=filterResponse(x.id,f,R,C,L);result(`${fmt(response.gain)} V de salida para 1 V de entrada`,`${rlc?'Resonancia f0':'Corte fc'} = ${fmt(response.corner)} Hz · Ganancia ${fmt(20*Math.log10(Math.max(1e-12,response.gain)))} dB · ${response.gain<1e-9?'Fase indefinida en el cero ideal':`Fase ${fmt(response.phase*180/Math.PI)}°`}${rlc?` · Q = ${fmt(Math.sqrt(L/C)/R)}`:''}`);
 const minlog=Math.log10(response.corner)-2,maxlog=minlog+4;let points;const px=55+(Math.log10(f)-minlog)/4*520;
 // y=45 at 0 dB; y=225 at -60 dB.
 points=Array.from({length:401},(_,i)=>{const db=Math.max(-60,20*Math.log10(Math.max(1e-12,filterResponse(x.id,10**(minlog+i/100),R,C,L).gain)));return `${55+i*1.3},${45-db*3}`;}).join(' ');
 $('atlasPlot').innerHTML=`<svg viewBox="0 0 650 290" role="img" aria-label="Respuesta de amplitud en decibelios frente a frecuencia logarítmica"><rect width="650" height="290" rx="12" fill="#0b202b"/><g stroke="#345564">${[0,20,40,60].map(db=>`<path d="M55 ${45+db*3}H575"/>`).join('')}${[0,1,2,3,4].map(i=>`<path d="M${55+i*130} 45V225"/>`).join('')}</g><g fill="#cce4ef" font-family="sans-serif" font-size="12">${[0,20,40,60].map(db=>`<text x="12" y="${50+db*3}">−${db}</text>`).join('')}${[0,1,2,3,4].map(i=>`<text text-anchor="middle" x="${55+i*130}" y="247">${fmt(10**(minlog+i))}</text>`).join('')}<text x="55" y="25">Ganancia (dB)</text><text x="210" y="279">Frecuencia (Hz) · escala logarítmica</text></g><polyline points="${points}" fill="none" stroke="#76e7b9" stroke-width="3"/>${px>=55&&px<=575?`<circle cx="${px}" cy="${45-Math.max(-60,20*Math.log10(Math.max(response.gain,1e-12)))*3}" r="6" fill="#ffca72"/>`:''}</svg>`;
 });}
 function showCircuits(){section='circuits';selected=null;render();}
 document.addEventListener('circuitlab:circuit-open',()=>{if(section!=='circuits')showCircuits();});render();return {showCircuits};
}
